// AOT变量函数dispatch：支持所有AOT注册的builtin函数、用户函数和静态方法
fn aot_dispatch_callable(name: []const u8, args: []const runtime.Value, allocator: std.mem.Allocator) anyerror!runtime.Value {
    // 1. 检查是否是静态方法调用: "ClassName::methodName"
    if (std.mem.indexOf(u8, name, "::")) |sep_pos| {
        const class_name = name[0..sep_pos];
        const method_name = name[sep_pos + 2..];
        return aot_dispatch_static_method(class_name, method_name, args, allocator);
    }

    // 2. 检查是否是用户定义的函数
    const user_func_result = aot_dispatch_user_function(name, args, allocator);
    if (user_func_result) |result| {
        return result;
    } else |err| {
        if (err != error.UnknownFunction) return err;
    }

    // 3. 检查是否是 builtin 函数
    if (std.mem.eql(u8, name, "is_int")) {
        if (args.len > 0) return try runtime.php_is_int(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_nan")) {
        if (args.len > 0) return try runtime.php_is_nan(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_dir")) {
        if (args.len > 0) return try runtime.php_is_dir(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_dir")) {
        if (args.len > 0) return try runtime.php_is_dir(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_bool")) {
        if (args.len > 0) return try runtime.php_is_bool(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_null")) {
        if (args.len > 0) return try runtime.php_is_null(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_file")) {
        if (args.len > 0) return try runtime.php_is_file(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_file")) {
        if (args.len > 0) return try runtime.php_is_file(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_array")) {
        if (args.len > 0) return try runtime.php_is_array(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_float")) {
        if (args.len > 0) return try runtime.php_is_float(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_string")) {
        if (args.len > 0) return try runtime.php_is_string(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_object")) {
        if (args.len > 0) return try runtime.php_is_object(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_finite")) {
        if (args.len > 0) return try runtime.php_is_finite(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_scalar")) {
        if (args.len > 0) return try runtime.php_is_scalar(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_numeric")) {
        if (args.len > 0) return try runtime.php_is_numeric(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_iterable")) {
        if (args.len > 0) return try runtime.php_is_iterable(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_writable")) {
        if (args.len > 0) return try runtime.php_is_writable(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_readable")) {
        if (args.len > 0) return try runtime.php_is_readable(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_resource")) {
        if (args.len > 0) return try runtime.php_is_resource(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_callable")) {
        if (args.len > 0) return try runtime.php_is_callable(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_resource")) {
        if (args.len > 0) return try runtime.php_is_resource(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_infinite")) {
        if (args.len > 0) return try runtime.php_is_infinite(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_countable")) {
        if (args.len > 0) return try runtime.php_is_countable(args[0]);
        return runtime.Value.initNull();
    }
    if (std.mem.eql(u8, name, "is_subclass_of")) {
        if (args.len >= 2) return try runtime.php_is_subclass_of(args[0], args[1]);
        return runtime.Value.initNull();
    }

    return error.UnknownFunction;
}

// 分发用户定义的函数调用
fn aot_dispatch_user_function(name: []const u8, args: []const runtime.Value, allocator: std.mem.Allocator) !runtime.Value {
    if (std.mem.eql(u8, name, "__main__")) {
        return @"__main__"(runtime.Value.initNull(), args, allocator);
    }
    return error.UnknownFunction;
}

// 分发静态方法调用
fn aot_dispatch_static_method(class_name: []const u8, method_name: []const u8, args: []const runtime.Value, allocator: std.mem.Allocator) !runtime.Value {
    _ = class_name;
    _ = method_name;
    _ = args;
    _ = allocator;
    return error.UnknownFunction;
}

